import axios, { AxiosError, AxiosResponse } from 'axios';
import { INicknameState } from '../types';

export class NicknameServer {
    private state: INicknameState;
    constructor(state: INicknameState) {
        this.state = state;
    }

    public async submitNickname(): Promise<void> {
        this.state.resetErrorState();
        return axios.post(this.state.config.endpoint, {
            gamingSessionToken: this.state.config.sessionToken,
            operatorIdentifier: this.state.config.operatorId,
            operatorUserId: this.state.config.userId,
            nickname: this.state.nickname })
            .then((response) => {
                // nickname parroted back by the server
                this.state.nickname = response.data.nickname;
                this.state.nicknameAccepted = true;
                this.state.isSubmitting = false;
            }).catch((error: Error | AxiosError) => {
                if (axios.isAxiosError(error)) {
                    if (error.response) {
                        this.handleFailedSubmission(error.response);
                    }
                } else {
                    this.state.error.errors.push({ name: 'UnknownError', description: 'An unknown error has occured' });
                }

                this.state.error.hasErrored = true;
                this.state.isSubmitting = false;
            });
    }

    private handleFailedSubmission(response: AxiosResponse): void {
        this.state.error.errorCode = response.status || 0;
        switch (response.status) {
            case 400:
                this.state.error.errors.push({ name: 'MalformedRequest', description: 'The request was not in the form the api could use' });
                break;
            case 401:
                this.state.error.errors.push({ name: 'NotAuthenticated', description: 'The session token was not valid' });
                break;
            case 403:
                this.state.error.errors.push({ name: 'NotAuthorized', description: 'The session token was invalid' });
                break;
            case 405:
                this.state.error.errors.push({ name: 'RequestBlocked', description: 'The request to the server was blocked' });
                break;
            case 422:
                if (!response.data.errors.nickname) {
                    // should not hit unless issue with client data sent
                    this.state.error.errors.push({ name: 'Unknown', description: 'An issue has occured with the data passed on the request' });
                } else {
                    for (const errorInfo of response.data.errors.nickname) {
                        this.state.error.errors.push({ name: errorInfo, description: '' });
                    }
                }
                break;
            case 500:
                this.state.error.errors.push({ name: 'ServerError', description: 'The server is not responding to the request' });
                break;
            default:
                this.state.error.errors.push({ name: 'Generic', description: 'An unknown error has occured' });
                break;
        }
    }
}